\begin{tikzpicture}[font=\sffamily, line width=0.8pt]
  % left beaker and zinc solution
  \fill[black!10] (0,0) rectangle (3.2,2.8);
  \draw (0,4.2) -- (0,0) -- (3.2,0) -- (3.2,4.2);

  % right beaker and copper solution
  \fill[black!10] (6.8,0) rectangle (10,2.8);
  \draw (6.8,4.2) -- (6.8,0) -- (10,0) -- (10,4.2);

  % electrodes
  \fill[black!50] (1.3,0.2) rectangle (1.55,5.2);
  \draw (1.3,0.2) rectangle (1.55,5.2);
  \fill[black!50] (8.3,0.2) rectangle (8.55,5.2);
  \draw (8.3,0.2) rectangle (8.55,5.2);

  % external circuit with voltmeter above the middle
  \draw (1.42,5.2) -- (1.42,7.0) -- (4.5,7.0);
  \draw (5.5,7.0) -- (8.42,7.0) -- (8.42,5.2);
  \draw (5,7) circle (0.5);
  \node at (5,7) {V};

  % salt bridge: inverted U tube dipping into both solutions
  \draw[line width=1.6pt] (2.6,1.2) -- (2.6,4.4) -- (7.4,4.4) -- (7.4,1.2);

  % labels
  \node[anchor=east] at (1.2,5.6) {zinc};
  \node[anchor=west] at (8.6,5.6) {copper};
  \node at (5,3.3) {salt bridge};
  \node[anchor=north] at (1.6,-0.1) {1.0 mol dm$^{-3}$ ZnSO$_4$(aq)};
  \node[anchor=north] at (8.4,-0.1) {1.0 mol dm$^{-3}$ CuSO$_4$(aq)};

  % caption
  \node[anchor=north] at (5,-1.2) {\textbf{Fig. 6.1}};
\end{tikzpicture}
